-- OvalTrack consolidated snapshot
-- PostgreSQL/psql script. Loads the snapshot in foreign-key dependency order.
BEGIN;
TRUNCATE TABLE events, matches_players, event_types, matches, division_players, division_coaches, divisions, clubs, users, persons RESTART IDENTITY CASCADE;

-- Break the clubs -> users -> persons -> clubs cycle by assigning the admin last.
UPDATE public.clubs SET admin_user_id = '11111111-1111-1111-1111-000000000001'::uuid WHERE id = '11111111-1111-1111-1111-000000000010'::uuid;
COMMIT;
